 * A cursor over the source text's code points that tracks line and column as
 * it advances, per the tab and line-feed rules of the specification.
 */
export class Scanner {
  constructor(source) {
    this.chars = Array.from(source)
    this.pos = 0
    this.line = 1
    this.column = 1
  }

  eof() {
    return this.pos >= this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.pos + offset]
  }

  advance() {
    const c = this.chars[this.pos]
    this.pos++
    if (c === '\n') {
      this.line++
      this.column = 1
    } else if (c === '\t') {
      this.column = this.column + 4 - ((this.column - 1) % 4)
    } else {
      this.column++
    }
    return c
  }
}
"}

