import { LexError } from './errors.js'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set('+-*/%=<>!(){}[],;.'.split(''))

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHexDigit = (c) => c !== undefined && /[0-9a-fA-F]/.test(c)
const isBinDigit = (c) => c === '0' || c === '1'
const isOctDigit = (c) => c !== undefined && c >= '0' && c <= '7'
const isLetter = (c) => c !== undefined && /[A-Za-z]/.test(c)
const isIdentStart = (c) => isLetter(c) || c === '_'
const isIdentContinue = (c) => isIdentStart(c) || isDigit(c)
const isTrailingRun = (c) => isIdentContinue(c)

/** Skips spaces, tabs, carriage returns, line feeds and comments. */
function skipTrivia(s) {
  while (!s.eof()) {
    const c = s.peek()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      s.advance()
      continue
    }
    if (c === '/' && s.peek(1) === '/') {
      while (!s.eof() && s.peek() !== '\n') s.advance()
      continue
    }
    if (c === '/' && s.peek(1) === '*') {
      const line = s.line
      const column = s.column
      s.advance()
      s.advance()
      let depth = 1
      while (depth > 0) {
        if (s.eof()) throw new LexError(line, column, 'unterminated block comment')
        if (s.peek() === '/' && s.peek(1) === '*') {
          s.advance()
          s.advance()
          depth++
        } else if (s.peek() === '*' && s.peek(1) === '/') {
          s.advance()
          s.advance()
          depth--
        } else {
          s.advance()
        }
      }
      continue
    }
    break
  }
}

/**
 * Scans a run of digits (per `isDigitFn`) with `_` allowed only between two
 * digits of the run. `lastWasDigit` seeds whether the character just before
 * the run started was itself a digit of this run.
 */
function scanDigitRun(s, isDigitFn, lastWasDigit = false) {
  let text = ''
  while (!s.eof()) {
    const c = s.peek()
    if (isDigitFn(c)) {
      text += s.advance()
      lastWasDigit = true
      continue
    }
    if (c === '_' && lastWasDigit && isDigitFn(s.peek(1))) {
      text += s.advance()
      lastWasDigit = false
      continue
    }
    break
  }
  return text
}

function scanNumber(s) {
  const line = s.line
  const column = s.column
  let text = s.advance()
  let prefixNoDigit = false

  if (text === '0' && /[xXbBoO]/.test(s.peek() || '')) {
    const p = s.peek()
    text += s.advance()
    const isDigitFn = p === 'x' || p === 'X' ? isHexDigit : p === 'b' || p === 'B' ? isBinDigit : isOctDigit
    const run = scanDigitRun(s, isDigitFn)
    text += run
    prefixNoDigit = run.length === 0
  } else {
    text += scanDigitRun(s, isDigit, true)
    if (s.peek() === '.' && isDigit(s.peek(1))) {
      text += s.advance()
      text += scanDigitRun(s, isDigit)
    }
    if (s.peek() === 'e' || s.peek() === 'E') {
      const after = s.peek(1)
      let expOk = false
      let signLen = 0
      if (isDigit(after)) {
        expOk = true
      } else if ((after === '+' || after === '-') && isDigit(s.peek(2))) {
        expOk = true
        signLen = 1
      }
      if (expOk) {
        text += s.advance()
        if (signLen) text += s.advance()
        text += scanDigitRun(s, isDigit)
      }
    }
  }

  let trailing = ''
  while (!s.eof() && isTrailingRun(s.peek())) trailing += s.advance()

  if (trailing || prefixNoDigit) {
    text += trailing
    throw new LexError(line, column, `invalid number ${text}`)
  }

  return { kind: 'number', text, line, column }
}

function scanIdent(s) {
  const line = s.line
  const column = s.column
  let text = ''
  while (!s.eof() && isIdentContinue(s.peek())) text += s.advance()
  const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
  return { kind, text, line, column }
}

function decodeHexEscape(s, backslashLine, backslashColumn) {
  s.advance() // 'x'
  let hex = ''
  for (let i = 0; i < 2; i++) {
    if (s.eof() || !isHexDigit(s.peek())) throw new LexError(backslashLine, backslashColumn, 'invalid escape \\x')
