  let hex = ''
  while (!s.eof() && isHexDigit(s.peek())) hex += s.advance()
  if (hex.length === 0) throw new LexError(backslashLine, backslashColumn, 'invalid escape \\u')
  if (s.peek() !== '}') throw new LexError(backslashLine, backslashColumn, 'invalid escape \\u')
  s.advance() // '}'
  const codePoint = parseInt(hex, 16)
  if (codePoint > 0x10ffff) throw new LexError(backslashLine, backslashColumn, 'invalid escape \\u')
  return String.fromCodePoint(codePoint)
}

function scanString(s) {
  const line = s.line
  const column = s.column
  s.advance() // opening quote
  let value = ''
  while (true) {
    if (s.eof()) throw new LexError(line, column, 'unterminated string')
    const c = s.peek()
    if (c === '"') {
      s.advance()
      break
    }
    if (c === '\n') throw new LexError(s.line, s.column, 'newline in string')
    if (c === '\\') {
      const backslashLine = s.line
      const backslashColumn = s.column
      s.advance()
      if (s.eof()) throw new LexError(line, column, 'unterminated string')
      const e = s.peek()
      switch (e) {
        case 'n':
          value += '\n'
          s.advance()
          break
        case 't':
          value += '\t'
          s.advance()
          break
        case 'r':
          value += '\r'
          s.advance()
          break
        case '\\':
          value += '\\'
          s.advance()
          break
        case '"':
          value += '"'
          s.advance()
          break
        case '0':
          value += '\0'
          s.advance()
          break
        case 'x':
          value += decodeHexEscape(s, backslashLine, backslashColumn)
          break
        case 'u':
          value += decodeUnicodeEscape(s, backslashLine, backslashColumn)
          break
        default:
          throw new LexError(backslashLine, backslashColumn, `invalid escape \\${e}`)
      }
    } else {
      value += c
      s.advance()
    }
  }
  return { kind: 'string', value, line, column }
}

function scanRawString(s) {
  const line = s.line
  const column = s.column
  s.advance() // 'r'
  s.advance() // opening quote
  let value = ''
  while (true) {
    if (s.eof()) throw new LexError(line, column, 'unterminated string')
    const c = s.peek()
    if (c === '"') {
      s.advance()
      break
    }
    value += c
    s.advance()
  }
  return { kind: 'rawstring', value, line, column }
}

function matchPunct(s) {
  const line = s.line
  const column = s.column
  const two = (s.peek() || '') + (s.peek(1) || '')
  if (TWO_CHAR_PUNCT.has(two)) {
    s.advance()
    s.advance()
    return { kind: 'punct', text: two, line, column }
  }
  const one = s.peek()
  if (ONE_CHAR_PUNCT.has(one)) {
    s.advance()
    return { kind: 'punct', text: one, line, column }
  }
  return null
}

function nextToken(s) {
  skipTrivia(s)
  if (s.eof()) return null
  const c = s.peek()
  if (c === '"') return scanString(s)
  if (c === 'r' && s.peek(1) === '"') return scanRawString(s)
  if (isIdentStart(c)) return scanIdent(s)
  if (isDigit(c)) return scanNumber(s)
  const punct = matchPunct(s)
  if (punct) return punct
  const line = s.line
  const column = s.column
  throw new LexError(line, column, `unexpected character ${c}`)
}

/** Scans `source` fully, returning every token in order. Throws `LexError`. */
export function tokenize(source) {
  const s = new Scanner(source)
  const tokens = []
  while (true) {
    const token = nextToken(s)
    if (token === null) break
    tokens.push(token)
  }
  return tokens
}
