/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { tokenize } from './lexer.js'
import { LexError } from './errors.js'

const KIND_ORDER = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function bodyOf(token) {
  return token.kind === 'string' || token.kind === 'rawstring' ? JSON.stringify(token.value) : token.text
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'tokens' && mode !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const source = readFileSync(0, 'utf8')

  let tokens
  try {
    tokens = tokenize(source)
  } catch (err) {
    if (err instanceof LexError) {
      process.stderr.write(`error: ${err.line}:${err.column}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  let output
  if (mode === 'tokens') {
    output = tokens.map((t) => `${t.line}:${t.column} ${t.kind} ${bodyOf(t)}\n`).join('')
  } else {
    const counts = Object.fromEntries(KIND_ORDER.map((k) => [k, 0]))
    for (const t of tokens) counts[t.kind]++
    output = KIND_ORDER.map((k) => `${k} ${counts[k]}\n`).join('') + `total ${tokens.length}\n`
  }

  process.stdout.write(output)
  process.exit(0)
}

main()
